questions.questionText:
Assume C11. What does the following embedded C fragment print?

#include <stdio.h>
#define RX_READY 0x01u
#define TX_EMPTY 0x02u
int main(void) {
    unsigned int status = 0x16u;   /* value read from a UART status register */
    int rx = (status & RX_READY) != 0;
    int tx = (status & TX_EMPTY) != 0;
    unsigned int err = (status >> 3) & 0x3u;
    printf("%d %d %u\n", rx, tx, err);
    return 0;
}

