/* spin lock built on an atomic test-and-set */
volatile int sem = 0;            /* 0 = free, 1 = busy   */

void enter_critical(void) {
    while (test_and_set(&sem) == 1)
        ;                        /* busy-wait: still locked */
}

void leave_critical(void) {
    sem = 0;                     /* release the resource */
}
